        mockMvc.perform(get("/api/schedule/publications/2026-09-26/2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2));
    }

    @Test
    void cancelBeforePublishIsIdempotent() throws Exception {
